import java.util.*;
import java.io.*;

public class Main {
    static class MCF {
        int n;
        long INF = (long)1e9;
        long[] prio, pot, curflow;
        int[] prevedge, prevnode;
        PriorityQueue<Pair> q;
        static class Edge {
            int to, rev;
            long f, cap;
            long cost;
            Edge(int to, int rev, long f, long cap, long cost) {
                this.to = to;
                this.rev = rev;
                this.f = f;
                this.cap = cap;
                this.cost = cost;
            }
        }
        ArrayList<ArrayList<Edge>> g;

        public MCF(int n) {
            this.n = n;
            prio = new long[n];
            pot = new long[n];
            curflow = new long[n];
            prevedge = new int[n];
            prevnode = new int[n];
            g = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
            q = new PriorityQueue<>(Comparator.comparingLong(p -> p.fst));
        }

        void add_edge(int s, int t, long cap, long cost) {
            g.get(s).add(new Edge(t, g.get(t).size(), 0, cap, cost));
            g.get(t).add(new Edge(s, g.get(s).size() - 1, 0, 0, -cost));
        }

        Pair get_flow(int s, int t) {
            long flow = 0;
            long flowcost = 0;
            while (true) {
                Arrays.fill(prio, INF);
                prio[s] = 0;
                curflow[s] = Long.MAX_VALUE;
                q.clear();
                q.add(new Pair(0, s));
                while (!q.isEmpty()) {
                    Pair cur = q.poll();
                    long d = cur.fst;
                    int u = cur.snd;
                    if (d != prio[u]) continue;
                    for (int i = 0; i < g.get(u).size(); i++) {
                        Edge e = g.get(u).get(i);
                        int v = e.to;
                        if (e.cap <= e.f) continue;
                        long nprio = prio[u] + e.cost + pot[u] - pot[v];
                        if (prio[v] > nprio) {
                            prio[v] = nprio;
                            q.add(new Pair(nprio, v));
                            prevnode[v] = u;
                            prevedge[v] = i;
                            curflow[v] = Math.min(curflow[u], e.cap - e.f);
                        }
                    }
                }
                if (prio[t] == INF) break;
                for (int i = 0; i < n; i++) {
                    pot[i] += prio[i];
                }
                long df = Math.min(curflow[t], Long.MAX_VALUE - flow);
                flow += df;
                for (int v = t; v != s; v = prevnode[v]) {
                    Edge e = g.get(prevnode[v]).get(prevedge[v]);
                    e.f += df;
                    g.get(v).get(e.rev).f -= df;
                    flowcost += df * e.cost;
                }
            }
            return new Pair(flow, flowcost);
        }
    }

    static class Pair {
        long fst;
        int snd;
        Pair(long fst, int snd) {
            this.fst = fst;
            this.snd = snd;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int T = 500; // assuming this works
        int N = n * T;
        MCF mcf = new MCF(N + 2);
        long INF = (long)1e9;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                mcf.add_edge(i * T + j, i * T + j + 1, INF, c);
            }
        }
        for (int i = 0; i < T; i++) {
            mcf.add_edge(i, N + 1, INF, 0);
        }
        int[] xArr = new int[k];
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(br.readLine()) - 1;
            xArr[i] = x;
            mcf.add_edge(N, x * T, 1, 0);
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            for (int j = 0; j < T - 1; j++) {
                int cur = 1;
                for (int _ = 0; _ < k; _++) {
                    mcf.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
                    mcf.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
                    cur += 2;
                }
            }
        }
        Pair p = mcf.get_flow(N, N + 1);
        if (p.fst != k) {
            System.out.println("0");
        } else {
            System.out.println(p.snd);
        }
    }
}
